import math

def shift(s) -> int:
	for i in range(1, len(s)):
		if s == s[i:] + s[:i]:
			return i
	return len(s)

def solve():
	n = int(input())
	s = input()
	p = [int(x) - 1 for x in input().split()]
	vis = [False] * n
	ans = 1
	for i in range(n):
		if vis[i]:
			continue
		ss = ''
		j = i
		ss += s[j]
		vis[j] = True
		j = p[j]
		while j != i:
			ss += s[j]
			vis[j] = True
			j = p[j]
		ln = shift(ss)
		ans = ans * ln // math.gcd(ans, ln)
	print(ans)
t = int(input())
for _ in range(t):
	solve()
